use realm_agent::policy::*;
#[test]fn strict_scope_rank_and_unknown(){let t=r#"{"schema_version":1,"revision":2,"enabled":true,"scope":{"mode":"world_pvp","min_opponents":1,"max_opponents":2},"predicates":{"adv":{"all":[{"field":"self.health_pct","op":"gte","value":60},{"field":"self.ready_spells","op":"contains","value":116}]}},"phases":[{"id":"engage","rules":[{"id":"frost","owner":"mage","priority":5,"when":{"ref":"adv"},"action":{"kind":"cast","ability":"mage.frostbolt","target":"primary_enemy"}}]}]}"#;let p=parse(t).unwrap();let mut o=Observation::default();o.phase="engage".into();o.opponent_count=1;o.numbers.insert("self.health_pct".into(),80.);o.sets.insert("self.ready_spells".into(),[116].into_iter().collect());let(c,tr)=rank(&p,&o,10,0);println!("c={} t={:?}",c.len(),tr.iter().map(|x|(&x.reason,x.unknown,x.eligible)).collect::<Vec<_>>());assert_eq!(c.len(),1);assert!(tr[0].eligible);o.sets.clear();let(c,tr)=rank(&p,&o,10,0);assert!(c.is_empty()&&tr[0].unknown)}
#[test]fn hot_publish_keeps_generation(){let p=parse(r#"{"schema_version":1,"revision":1,"enabled":false,"scope":{"mode":"world_pvp"},"phases":[{"id":"p","rules":[]}] }"#).unwrap();let s=Store::new(p);s.stage(r#"{"schema_version":1,"revision":2,"enabled":true,"scope":{"mode":"world_pvp"},"phases":[{"id":"p","rules":[]}] }"#).unwrap();let a=s.publish().unwrap();assert_eq!(a.generation,1);assert!(s.stage("bad").is_err());assert_eq!(s.current().generation,1)}
